{
  "name": "00bx-kiro-gateway",
  "version": "1.0.9",
  "description": "AI SDK provider that lets OpenCode use Claude models through Kiro CLI's free-tier credits",
  "main": "dist/index.js",
  "module": "dist/index.mjs",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.mts",
      "import": "./dist/index.mjs",
      "require": "./dist/index.js",
      "default": "./dist/index.mjs"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsup",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "ai-sdk",
    "opencode",
    "kiro",
    "claude",
    "provider",
    "free",
    "codewhisperer"
  ],
  "author": "00bx",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/00bx/00bx-kiro-gateway"
  },
  "homepage": "https://github.com/00bx/00bx-kiro-gateway#readme",
  "bugs": {
    "url": "https://github.com/00bx/00bx-kiro-gateway/issues"
  },
  "devDependencies": {
    "@ai-sdk/provider": "^3.0.8",
    "@types/node": "^22.0.0",
    "tsup": "^8.0.0",
    "typescript": "^5.7.0"
  }
}
